import * as t from "tap";
import { getApiAuthType as get } from "./getApiAuthType";
import type { Context } from "../Context";

function getContext(
  headers: Record<string, string> = {},
  cookies: Record<string, string> = {}
): Context {
  return {
    method: "GET",
    route: "/test",
    headers,
    body: undefined,
    remoteAddress: "",
    url: `http://localhost/test`,
    routeParams: {},
    query: {},
    cookies,
    source: "test",
  };
}

t.test("it detects authorization header", async (t) => {
  t.same(get(getContext({ authorization: "Bearer token" })), [
    { type: "http", scheme: "bearer" },
  ]);
  t.same(get(getContext({ authorization: "Basic base64" })), [
    { type: "http", scheme: "basic" },
  ]);
  t.same(get(getContext({ authorization: "custom" })), [
    { type: "apiKey", in: "header", name: "Authorization" },
  ]);
});

t.test("it detects api keys", async (t) => {
  t.same(get(getContext({ "x-api-key": "token" })), [
    { type: "apiKey", in: "header", name: "x-api-key" },
  ]);
  t.same(get(getContext({ "api-key": "token" })), [
    { type: "apiKey", in: "header", name: "api-key" },
  ]);
});

t.test("it detects auth cookies", async (t) => {
  t.same(get(getContext({}, { "api-key": "token" })), [
    { type: "apiKey", in: "cookie", name: "api-key" },
  ]);
  t.same(get(getContext({}, { session: "test" })), [
    {
      type: "apiKey",
      in: "cookie",
      name: "session",
    },
  ]);
});

t.test("no auth", async (t) => {
  t.same(get(getContext()), undefined);
  t.same(get(getContext({})), undefined);
  t.same(get(getContext({ authorization: "" })), undefined);
  // @ts-expect-error Testing edge case
  t.same(get({}), undefined);
});

import * as t from "tap";
import { mergeApiAuthTypes as merge } from "./mergeApiAuthTypes";

t.test("it works", async (t) => {
  t.same(
    merge(
      [
        {
          type: "http",
          scheme: "bearer",
        },
        {
          type: "apiKey",
          in: "header",
          name: "x-api-key",
        },
      ],
      [
        {
          type: "http",
          scheme: "bearer",
        },
        {
          type: "http",
          scheme: "basic",
        },
        {
          type: "apiKey",
          in: "header",
          name: "x-api-key-v2",
        },
      ]
    ),
    [
      {
        type: "http",
        scheme: "bearer",
      },
      {
        type: "apiKey",
        in: "header",
        name: "x-api-key",
      },
      {
        type: "http",
        scheme: "basic",
      },
      {
        type: "apiKey",
        in: "header",
        name: "x-api-key-v2",
      },
    ]
  );

  t.same(merge(undefined, undefined), undefined);

  t.same(
    merge(
      [
        {
          type: "http",
          scheme: "bearer",
        },
      ],
      undefined
    ),
    [
      {
        type: "http",
        scheme: "bearer",
      },
    ]
  );

  t.same(
    merge(undefined, [
      {
        type: "http",
        scheme: "digest",
      },
    ]),
    [
      {
        type: "http",
        scheme: "digest",
      },
    ]
  );
});

import * as FakeTimers from "@sinonjs/fake-timers";
import * as t from "tap";
import { ReportingAPIForTesting } from "./ReportingAPIForTesting";
import { ReportingAPIRateLimitedServerSide } from "./ReportingAPIRateLimitedServerSide";
import { Event } from "./Event";
import { Token } from "./Token";

function generateStartedEvent(): Event {
  return {
    type: "started",
    time: Date.now(),
    agent: {
      version: "1.0.0",
      dryMode: false,
      hostname: "hostname",
      packages: {},
      ipAddress: "ipAddress",
      preventedPrototypePollution: false,
      nodeEnv: "",
      os: {
        name: "os",
        version: "version",
      },
      incompatiblePackages: {
        prototypePollution: {},
      },
      stack: [],
      serverless: false,
      library: "firewall-node",
      platform: {
        version: "version",
        arch: "arch",
      },
    },
  };
}

t.test("it stops sending requests if rate limited", async (t) => {
  const clock = FakeTimers.install();

  const api = new ReportingAPIForTesting();
  const rateLimitedAPI = new ReportingAPIRateLimitedServerSide(api);
  const token = new Token("token");

  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: true,
    endpoints: [],
    heartbeatIntervalInMS: 10 * 60 * 1000,
    configUpdatedAt: 0,
    blockedUserIds: [],
    allowedIPAddresses: [],
    blockNewOutgoingRequests: false,
    domains: [],
    excludedUserIdsFromRateLimiting: [],
  });
  t.match(api.getEvents(), [{ type: "started" }]);

  api.setResult({ success: false, error: "timeout" });
  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: false,
    error: "timeout",
  });
  t.match(api.getEvents(), [{ type: "started" }, { type: "started" }]);

  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: false,
    error: "timeout",
  });
  t.match(api.getEvents(), [
    { type: "started" },
    { type: "started" },
    { type: "started" },
  ]);

  api.setResult({ success: false, error: "rate_limited" });
  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: false,
    error: "rate_limited",
  });
  t.match(api.getEvents(), [
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
  ]);

  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: false,
    error: "rate_limited",
  });
  t.match(api.getEvents(), [
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
  ]);

  clock.tick(30 * 60 * 1000);
  api.setResult({
    success: true,
    endpoints: [],
    heartbeatIntervalInMS: 10 * 60 * 1000,
    configUpdatedAt: 0,
    blockedUserIds: [],
    allowedIPAddresses: [],
    excludedUserIdsFromRateLimiting: [],
  });
  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: true,
    endpoints: [],
    heartbeatIntervalInMS: 10 * 60 * 1000,
    configUpdatedAt: 0,
    blockedUserIds: [],
    allowedIPAddresses: [],
    excludedUserIdsFromRateLimiting: [],
  });
  t.match(api.getEvents(), [
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
  ]);

  api.setResult({ success: false, error: "rate_limited" });
  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: false,
    error: "rate_limited",
  });
  t.match(api.getEvents(), [
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
  ]);

  t.same(await rateLimitedAPI.report(token, generateStartedEvent(), 5000), {
    success: false,
    error: "rate_limited",
  });
  t.match(api.getEvents(), [
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
    { type: "started" },
  ]);

  clock.uninstall();
});

import {
  createTRPCClient,
  httpBatchStreamLink,
  httpSubscriptionLink,
  splitLink,
} from "@trpc/client";

import type { AppRouter } from "../server/router.js";
import { deepEqual, rejects } from "assert/strict";

const port = process.env.PORT || "4000";
const path = process.env.PATH || "";

const trpc = createTRPCClient<AppRouter>({
  links: [
    splitLink({
      condition: (op) => op.type === "subscription",
      true: httpSubscriptionLink({
        url: `http://localhost:${port}`,
      }),
      false: httpBatchStreamLink({
        url: `http://localhost:${port}`,
      }),
    }),
  ],
});

async function main() {
  const expectBlocking = process.env.AIKIDO_BLOCK === "true";

  await trpc.cats.reset.mutate();

  const cats = await trpc.cats.list.query();

  deepEqual(cats, [], "Cats should be empty initially");

  const createdCat = await trpc.cats.create.mutate({ name: "miau" });

  deepEqual(
    createdCat,
    { changes: 1, lastInsertRowid: 1 },
    "Cat should be created"
  );

  const cat = await trpc.cats.byName.query("miau");
  deepEqual(cat, { petname: "miau" }, "Cat should be found by name");

  if (expectBlocking) {
    await rejects(
      () => trpc.cats.byName.query("test' OR '1'='1"),
      "SQL injection should be blocked"
    );
  } else {
    const injectedCat = await trpc.cats.byName.query("' OR '1'='1");
    deepEqual(
      injectedCat,
      { petname: "miau" },
      "SQL injection should return the first cat"
    );
  }

  process.exit(0);
}

void main();

import * as t from "tap";
import { ServiceConfig } from "./ServiceConfig";
import type { Context } from "./Context";
import type { EndpointConfig } from "./Config";
t.test("it returns false if empty rules", async () => {
  const config = new ServiceConfig([], 0, [], []);
  t.same(config.getLastUpdatedAt(), 0);
  t.same(config.isUserBlocked("id"), false);
  t.same(config.isBypassedIP("1.2.3.4"), false);
  t.same(
    config.getEndpoints({
      url: undefined,
      method: undefined,
      route: undefined,
    }),
    []
  );
});

t.test("realtime updates enabled defaults to false", async (t) => {
  const config = new ServiceConfig([], 0, [], []);
  t.same(config.isRealtimeUpdatesEnabled(), false);
});

t.test("it updates realtime updates enabled", async (t) => {
  const config = new ServiceConfig([], 0, [], []);

  config.updateEnabledFeatures(["realtime_updates"]);
  t.same(config.isRealtimeUpdatesEnabled(), true);

  config.updateEnabledFeatures([]);
  t.same(config.isRealtimeUpdatesEnabled(), false);

  config.updateEnabledFeatures(["some_other_feature"]);
  t.same(config.isRealtimeUpdatesEnabled(), false);
});

t.test("it works", async () => {
  const config = new ServiceConfig(
    [
      {
        method: "GET",
        route: "/foo",
        forceProtectionOff: false,
        rateLimiting: {
          enabled: false,
          maxRequests: 0,
          windowSizeInMS: 0,
        },
      },
      {
        method: "POST",
        route: "/foo",
        forceProtectionOff: true,
        rateLimiting: {
          enabled: false,
          maxRequests: 0,
          windowSizeInMS: 0,
        },
      },
      {
        method: "POST",
        route: /fly+/.source,
        forceProtectionOff: true,
        rateLimiting: {
          enabled: false,
          maxRequests: 0,
          windowSizeInMS: 0,
        },
      },
    ],
    0,
    ["123"],
    []
  );

  t.same(config.isUserBlocked("123"), true);
  t.same(config.isUserBlocked("567"), false);
  t.same(
    config.getEndpoints({
      url: undefined,
      method: "GET",
      route: "/foo",
    }),
    [
      {
        method: "GET",
        route: "/foo",
        forceProtectionOff: false,
        allowedIPAddresses: undefined,
        rateLimiting: {
          enabled: false,
          maxRequests: 0,
          windowSizeInMS: 0,
        },
      },
    ]
  );
});

t.test(
  "endpoint config does not inherit forceProtectionOff from a polluted Object.prototype",
  async (t) => {
    // @ts-expect-error Simulating prototype pollution
    Object.prototype.forceProtectionOff = true;
    t.teardown(() => {
      // @ts-expect-error Simulating prototype pollution
      delete Object.prototype.forceProtectionOff;
    });

    const endpointWithoutOwnFlag = {
      method: "GET",
      route: "/foo",
      rateLimiting: { enabled: false, maxRequests: 0, windowSizeInMS: 0 },
    } as unknown as EndpointConfig;

    const config = new ServiceConfig([endpointWithoutOwnFlag], 0, [], []);

    const context = { url: undefined, method: "GET", route: "/foo" };

    t.same(config.getEndpoints(context)[0].forceProtectionOff, undefined);
    t.same(config.isForceProtectionOffRoute(context), false);
  }
);

t.test("it checks if IP is bypassed", async () => {
  const config = new ServiceConfig([], 0, [], ["1.2.3.4"]);
  t.same(config.isBypassedIP("1.2.3.4"), true);
  t.same(config.isBypassedIP("1.2.3.5"), false);
});

t.test("ip blocking works", async () => {
  const config = new ServiceConfig([], 0, [], []);
  await config.updateFirewallLists({
    blockedIPAddresses: [
      {
        key: "geoip/Belgium;BE",
        source: "geoip",
        description: "description",
        ips: [
          "1.2.3.4",
          "192.168.2.1/24",
          "fd00:1234:5678:9abc::1",
          "fd00:3234:5678:9abc::1/64",
          "5.6.7.8/32",
        ],
      },
    ],
    allowedIPAddresses: [],
    monitoredIPAddresses: [],
    blockedUserAgents: "",
    monitoredUserAgents: "",
    userAgentDetails: [],
  });
  t.same(config.isIPAddressBlocked("1.2.3.4"), {
    blocked: true,
    reason: "description",
  });
  t.same(config.isIPAddressBlocked("2.3.4.5"), { blocked: false });
  t.same(config.isIPAddressBlocked("192.168.2.2"), {
    blocked: true,
    reason: "description",
  });
  t.same(config.isIPAddressBlocked("fd00:1234:5678:9abc::1"), {
    blocked: true,
    reason: "description",
  });
  t.same(config.isIPAddressBlocked("fd00:1234:5678:9abc::2"), {
    blocked: false,
  });
  t.same(config.isIPAddressBlocked("fd00:3234:5678:9abc::1"), {
    blocked: true,
    reason: "description",
  });
  t.same(config.isIPAddressBlocked("fd00:3234:5678:9abc::2"), {
    blocked: true,
    reason: "description",
  });
  t.same(config.isIPAddressBlocked("5.6.7.8"), {
    blocked: true,
    reason: "description",
  });
  t.same(config.isIPAddressBlocked("1.2"), { blocked: false });
});

t.test("it blocks bots", async () => {
  const config = new ServiceConfig([], 0, [], []);
  config.updateBlockedUserAgents("googlebot|bingbot");

  t.same(config.isUserAgentBlocked("googlebot"), { blocked: true });
  t.same(config.isUserAgentBlocked("123 bingbot abc"), { blocked: true });
  t.same(config.isUserAgentBlocked("bing"), { blocked: false });

  config.updateBlockedUserAgents("");

  t.same(config.isUserAgentBlocked("googlebot"), { blocked: false });
});

t.test("restricting access to some ips", async () => {
  const config = new ServiceConfig([], 0, [], []);
  await config.updateFirewallLists({
    blockedIPAddresses: [],
    allowedIPAddresses: [
      {
        key: "geoip/Belgium;BE",
        source: "geoip",
        description: "description",
        ips: ["1.2.3.4"],
      },
    ],
    monitoredIPAddresses: [],
    blockedUserAgents: "",
    monitoredUserAgents: "",
    userAgentDetails: [],
  });

  t.same(config.isAllowedIPAddress("1.2.3.4").allowed, true);
  t.same(config.isAllowedIPAddress("4.3.2.1").allowed, false);
  t.same(config.isAllowedIPAddress("127.0.0.1").allowed, true); // Always allow private ips

  await config.updateFirewallLists({
    blockedIPAddresses: [],
    allowedIPAddresses: [],
    monitoredIPAddresses: [],
    blockedUserAgents: "",
    monitoredUserAgents: "",
    userAgentDetails: [],
  });
  t.same(config.isAllowedIPAddress("1.2.3.4").allowed, true);
  t.same(config.isAllowedIPAddress("127.0.0.1").allowed, true);
  t.same(config.isAllowedIPAddress("4.3.2.1").allowed, true);
});

t.test("only allow some ips: empty list", async () => {
  const config = new ServiceConfig([], 0, [], []);
  await config.updateFirewallLists({
    blockedIPAddresses: [],
    allowedIPAddresses: [
      {
        key: "geoip/Belgium;BE",
        source: "geoip",
        description: "description",
        ips: [],
      },
    ],
    monitoredIPAddresses: [],
    blockedUserAgents: "",
    monitoredUserAgents: "",
    userAgentDetails: [],
  });

  t.same(config.isAllowedIPAddress("1.2.3.4").allowed, true);
  t.same(config.isAllowedIPAddress("4.3.2.1").allowed, true);
});

t.test("bypassed ips support cidr", async () => {
  const config = new ServiceConfig([], 0, [], ["192.168.2.0/24", "::1"]);

  t.same(config.isBypassedIP("192.168.2.32"), true);
  t.same(config.isBypassedIP("::1"), true);
  t.same(config.isBypassedIP("::2"), false);
  t.same(config.isBypassedIP("10.0.0.1"), false);

  config.updateConfig([], 0, [], ["invalid", "2002::1/124", "127.0.0.1"]);

  t.same(config.isBypassedIP("2002::6"), true);
  t.same(config.isBypassedIP("2002::f"), true);
  t.same(config.isBypassedIP("2002::10"), false);
  t.same(config.isBypassedIP("127.0.0.1"), true);
  t.same(config.isBypassedIP("192.168.2.1"), false);
  t.same(config.isBypassedIP("::1"), false);

  config.updateConfig(
    [],
    0,
    [],
    ["0", "123.123.123.1/32", "234.0.0.0/8", "999.999.999.999", "::1/128"]
  );

  t.same(config.isBypassedIP("123.123.123.1"), true);
  t.same(config.isBypassedIP("124.123.123.1"), false);
  t.same(config.isBypassedIP("234.1.2.3"), true);
  t.same(config.isBypassedIP("235.1.2.3"), false);
  t.same(config.isBypassedIP("127.0.0.1"), false);
  t.same(config.isBypassedIP("999.999.999.999"), false);
  t.same(config.isBypassedIP("::1"), true);
  t.same(config.isBypassedIP("::2"), false);

  config.updateConfig([], 0, [], []);

  t.same(config.isBypassedIP("123.123.123.1"), false);
  t.same(config.isBypassedIP("999.999.999.999"), false);
});

t.test("it sets and updates monitored IP lists", async (t) => {
  const config = new ServiceConfig([], 0, [], []);

  t.same(config.getMatchingMonitoredIPListKeys("9.9.9.9"), []);
  t.same(config.getMatchingMonitoredIPListKeys("1.2.3.4"), []);

  await config.updateFirewallLists({
    blockedIPAddresses: [],
    allowedIPAddresses: [],
    monitoredIPAddresses: [
      {
        key: "tor/exit_nodes",
        source: "tor",
        description: "due to tor usage",
        ips: ["1.2.3.0/24", "9.9.9.9"],
      },
    ],
    blockedUserAgents: "",
    monitoredUserAgents: "",
    userAgentDetails: [],
  });

  t.same(config.getMatchingMonitoredIPListKeys("9.9.9.9"), ["tor/exit_nodes"]);
  t.same(config.getMatchingMonitoredIPListKeys("1.2.3.4"), ["tor/exit_nodes"]);

  await config.updateFirewallLists({
    blockedIPAddresses: [],
    allowedIPAddresses: [],
    monitoredIPAddresses: [],
    blockedUserAgents: "",
    monitoredUserAgents: "",
    userAgentDetails: [],
  });

  t.same(config.getMatchingMonitoredIPListKeys("9.9.9.9"), []);
  t.same(config.getMatchingMonitoredIPListKeys("1.2.3.4"), []);
});

t.test("it returns matching IP lists keys", async (t) => {
  const config = new ServiceConfig([], 0, [], []);

  await config.updateFirewallLists({
    monitoredIPAddresses: [
      {
        key: "tor/exit_nodes",
        source: "tor",
        description: "due to tor usage",
        ips: ["9.9.9.9"],
      },
      {
        key: "known_threat_actors/public_scanners",
        source: "tor",
        description: "due to tor usage",
        ips: ["9.9.9.9/32"],
      },
    ],
    blockedIPAddresses: [
      {
        key: "geoip/Belgium;BE",
        source: "geoip",
        description: "description",
        ips: ["8.8.8.8"],
      },
      {
        key: "geoip/Germany;DE",
        source: "geoip",
        description: "description",
        ips: ["8.8.8.8/32"],
      },
    ],
    allowedIPAddresses: [
      {
        key: "geoip/Belgium;BE",
        source: "geoip",
        description: "description",
        ips: ["7.7.7.7"],
      },
    ],
    blockedUserAgents: "",
    monitoredUserAgents: "",
    userAgentDetails: [],
  });

  t.same(config.getMatchingBlockedIPListKeys("9.9.9.9"), []);
  t.same(config.getMatchingMonitoredIPListKeys("9.9.9.9"), [
    "tor/exit_nodes",
    "known_threat_actors/public_scanners",
  ]);
  t.same(config.getMatchingBlockedIPListKeys("8.8.8.8"), [
    "geoip/Belgium;BE",
    "geoip/Germany;DE",
  ]);
  t.same(config.getMatchingMonitoredIPListKeys("8.8.8.8"), []);
  t.same(config.getMatchingBlockedIPListKeys("7.7.7.7"), []);
  t.same(config.getMatchingMonitoredIPListKeys("7.7.7.7"), []);
});

t.test("should return all matching user agent patterns", async (t) => {
  const config = new ServiceConfig([], 0, [], []);
  config.updateUserAgentDetails([
    {
      key: "list1",
      pattern: "a|b|c",
    },
    {
      key: "list2",
      pattern: "b",
    },
  ]);
  t.same(config.getMatchingUserAgentKeys("a"), ["list1"]);
  t.same(config.getMatchingUserAgentKeys("A"), ["list1"]);
  t.same(config.getMatchingUserAgentKeys("b"), ["list1", "list2"]);
  t.same(config.getMatchingUserAgentKeys("c"), ["list1"]);
  t.same(config.getMatchingUserAgentKeys("d"), []);
});

t.test("it clears RegExp when updating with empty pattern", async (t) => {
  const config = new ServiceConfig([], 0, [], []);
  config.updateBlockedUserAgents("googlebot");
  config.updateMonitoredUserAgents("googlebot");
  config.updateUserAgentDetails([
    {
      key: "googlebot",
      pattern: "googlebot",
    },
  ]);

  config.updateBlockedUserAgents("");
  config.updateMonitoredUserAgents("");
  config.updateUserAgentDetails([]);

  t.same(config.isMonitoredUserAgent("googlebot"), false);
  t.same(config.isUserAgentBlocked("googlebot"), { blocked: false });
  t.same(config.getMatchingUserAgentKeys("googlebot"), []);
});

t.test(
  "it does not throw error when updating user agent lists with invalid patterns",
  async (t) => {
    const config = new ServiceConfig([], 0, [], []);

    config.updateBlockedUserAgents("googlebot");
    config.updateMonitoredUserAgents("googlebot");
    config.updateUserAgentDetails([
      {
        key: "googlebot",
        pattern: "googlebot",
      },
    ]);

    config.updateBlockedUserAgents("[");
    config.updateMonitoredUserAgents("[");
    config.updateUserAgentDetails([
      {
        key: "googlebot",
        pattern: "[",
      },
    ]);

    t.same(config.isMonitoredUserAgent("googlebot"), false);
    t.same(config.isUserAgentBlocked("googlebot"), { blocked: false });
    t.same(config.getMatchingUserAgentKeys("googlebot"), []);
  }
);

t.test("it atomically updates firewall lists", async (t) => {
  const config = new ServiceConfig([], 0, [], []);
  await config.updateFirewallLists({
