  // Wait for the server to start
  timeout(5000)
    .then(() => {
      return Promise.all([
        fetch("http://127.0.0.1:1337/admin/register-admin", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({}),
          signal: AbortSignal.timeout(5000),
        }),
      ]);
    })
    .then(([registerAdmin]) => {
      t.equal(registerAdmin.status, 400);
    })
    .catch((error) => {
      t.fail(error.message);
    })
    .finally(() => {
      server.kill();
    });
});

