require("@aikidosec/firewall");

const http2 = require("http2");
const { readFile } = require("fs/promises");
const { join } = require("path");

async function main() {
  const key = await readFile(join(__dirname, "key.pem"));
  const cert = await readFile(join(__dirname, "cert.pem"));
  const server = http2.createSecureServer({ key, cert });

  server.on("stream", (stream, headers) => {
    const method = headers[":method"];

    if (method !== "GET") {
      stream.respond({
        ":status": 405,
      });
      stream.end("Method Not Allowed");
      return;
    }

    let rawBody = "";
    stream.on("data", (chunk) => {
      rawBody += chunk;
    });

    stream.on("end", async () => {
      const requestUrl = new URL(
        headers[":path"],
        headers[":scheme"] + "://" + headers[":authority"]
      );

      const url = requestUrl.searchParams.get("url");

      if (typeof url !== "string") {
        stream.respond({
          ":status": 400,
        });
        stream.end("Missing URL in request query");
        return;
      }

      try {
        const response = await fetch(url);
        const data = await response.arrayBuffer();
        stream.respond({
          "content-type": "image/jpeg",
          ":status": 200,
        });
        stream.end(Buffer.from(data));
      } catch (error) {
        console.error(error.message);
        stream.respond({
          ":status": 500,
        });
        stream.end(error.message);
      }
    });
  });

  const port = getPort();
  server.listen(port, () => {
    console.log(`Listening on port ${port}`);
  });
}

function getPort() {
  const port = parseInt(process.argv[2], 10) || 4000;

  if (isNaN(port)) {
    console.error("Invalid port");
    process.exit(1);
  }

  return port;
}

(async () => {
  try {
    await main();
  } catch (error) {
    console.error(error);
    process.exit(1);
  }
})();

import { defineConfig } from "@adonisjs/auth";
import { tokensGuard, tokensUserProvider } from "@adonisjs/auth/access_tokens";
import type {
  InferAuthenticators,
  InferAuthEvents,
  Authenticators,
} from "@adonisjs/auth/types";

const authConfig = defineConfig({
  default: "api",
  guards: {
    api: tokensGuard({
      provider: tokensUserProvider({
        tokens: "accessTokens",
        model: () => import("#models/user"),
      }),
    }),
  },
});

export default authConfig;

/**
 * Inferring types from the configured auth
 * guards.
 */
declare module "@adonisjs/auth/types" {
  export interface Authenticators extends InferAuthenticators<
    typeof authConfig
  > {}
}
declare module "@adonisjs/core/types" {
  interface EventsList extends InferAuthEvents<Authenticators> {}
}

import type { HttpContext } from "@adonisjs/core/http";
import type { NextFn } from "@adonisjs/core/types/http";
import type { Authenticators } from "@adonisjs/auth/types";

/**
 * Auth middleware is used authenticate HTTP requests and deny
 * access to unauthenticated users.
 */
export default class AuthMiddleware {
  /**
   * The URL to redirect to, when authentication fails
   */
  redirectTo = "/login";

  async handle(
    ctx: HttpContext,
    next: NextFn,
    options: {
      guards?: (keyof Authenticators)[];
    } = {}
  ) {
    await ctx.auth.authenticateUsing(options.guards, {
      loginRoute: this.redirectTo,
    });
    return next();
  }
}

# AWS Batch

AWS Batch runs scripts in containers — there's no HTTP server involved. Zen can still track AI token usage (Bedrock, OpenAI, etc.) inside your batch jobs.

At the very beginning of your script, add the following line:

```js
const Zen = require("@aikidosec/firewall"); // <-- Include this before any other code or imports

async function main() {
  // Your batch job logic
}

main()
  .catch(console.error)
  .finally(() => Zen.shutdown());
```

or using `import` syntax:

```js
import Zen from "@aikidosec/firewall";

async function main() {
  // Your batch job logic
}

main()
  .catch(console.error)
  .finally(() => Zen.shutdown());
```

> [!NOTE]
> Many TypeScript projects use `import` syntax but still compile to CommonJS — in that case, the setup above works as-is. If your app runs as **native ESM** at runtime (e.g. `"type": "module"` in package.json), see [ESM setup](./esm.md) for additional steps.

The `Zen.shutdown()` call at the end makes sure all collected stats are sent before the process exits. See [graceful shutdown](./graceful-shutdown.md) for more details.

## Debug mode

If you need to debug the firewall, you can run your batch job with the environment variable `AIKIDO_DEBUG` set to `true`.

This will output debug information to the console (e.g. if the agent failed to start, no token was found, unsupported packages, ...).

# Bypass Zen for a specific request

Call `Zen.bypassRequest()` in a middleware or request handler to bypass Zen for this request. A bypassed request is fully excluded from Zen inspection and enforcement: Zen will not analyze the request, generate findings, or apply blocking rules for that traffic. Your application handles the request normally.

## What gets bypassed

- **Attack protection** — SQL injection, path traversal, command injection, and SSRF attacks are not blocked or reported
- **Rate limiting** — never triggered.
- **IP blocking** — Known Threat Actors, Tor traffic blocking/monitoring, country blocking, and custom IP allow/block lists are not checked.
- **Bot traffic blocking** — not checked.
- **User blocking** — blocked users are not blocked.
- **Statistics** — the request isn't counted, and doesn't count against your monitored request quota.
- **Attack wave protection** — the request doesn't count towards wave detection.
- **IDOR Protection** — SQL queries are not checked for IDOR vulnerabilities

## Usage

The following example shows how to disable Zen for a specific request in a Hono application.

```js
import { Hono } from "hono";
import Zen from "@aikidosec/firewall";

const app = new Hono();

app.use(async (c, next) => {
  // Add your custom logic here
  if (yourCustomLogic() === "true") {
    Zen.bypassRequest(); // <-- This disables Zen for this specific request
  }

  await next();
});

// Make sure to call Zen.bypassRequest() in a middleware before this to bypass Rate limiting and user blocking
Zen.addHonoMiddleware(app);

app.get("/", async (c) => {
  // Alternatively, you can also call Zen.bypassRequest() here to bypass attack blocking only for this specific route
  // This will however not bypass rate limiting or user blocking, as those are applied in the middleware

  // Your route logic here
  return c.text("Hello, World!");
});

// ...
```

> [!NOTE]
> Zen also has a built-in [Bypassed IPs](https://help.aikido.dev/zen-firewall/zen-features/bypassed-ips) feature without requiring code changes.

> [!WARNING]
> A bypassed request gets zero protection from Zen — no attack detection, no rate limiting, no blocking, no tracking. Ensure that your custom logic only bypasses requests that you fully trust.

const AUTH_SCHEMES = [
  "basic",
  "bearer",
  "digest",
  "dpop",
  "gnap",
  "hoba",
  "mutal",
  "negotiate",
  "privatetoken",
  "scram-sha-1",
  "scram-sha-256",
  "vapid",
] as const;
export type HTTPAuthScheme = (typeof AUTH_SCHEMES)[number];

/**
 * Checks if a string is a valid HTTP authentication scheme.
 * https://www.iana.org/assignments/http-authschemes/http-authschemes.xhtml
 */
export function isHTTPAuthScheme(scheme: string): scheme is HTTPAuthScheme {
  return AUTH_SCHEMES.includes(scheme.toLowerCase() as HTTPAuthScheme);
}

import { getFileExtension } from "./getFileExtension";

const LOWERCASE = "abcdefghijklmnopqrstuvwxyz".split("");
const UPPERCASE = LOWERCASE.map((char) => char.toUpperCase());
const NUMBERS = "0123456789".split("");
const SPECIAL = "!#$%^&*|;:<>".split("");
const KNOWN_WORD_SEPARATORS = ["-"];
const WHITE_SPACE = /\s+/;
const MINIMUM_LENGTH = 10;

export function looksLikeASecret(str: string) {
  if (str.length <= MINIMUM_LENGTH) {
    return false;
  }

  const hasNumber = NUMBERS.some((char) => str.includes(char));

  if (!hasNumber) {
    return false;
  }

  const hasLower = LOWERCASE.some((char) => str.includes(char));
  const hasUpper = UPPERCASE.some((char) => str.includes(char));
  const hasSpecial = SPECIAL.some((char) => str.includes(char));
  const charsets = [hasLower, hasUpper, hasSpecial];

  // If the string doesn't have at least 2 different charsets, it's not a secret
  if (charsets.filter((charset) => charset).length < 2) {
    return false;
  }

  // If the string has white space, it's not a secret
  if (WHITE_SPACE.test(str)) {
    return false;
  }

  if (KNOWN_WORD_SEPARATORS.some((separator) => str.includes(separator))) {
    return false;
  }

  // Ignore static assests with random file names, e.g. index.BRaz9DSe.css"
  // The function shouldDiscoverRoutes already checks for this, but it's executed after this function, so the route would already be /asset/:secret
  const extension = getFileExtension(str);
  if (extension && extension.length > 1 && extension.length < 6) {
    return false;
  }

  // Check uniqueness of characters in a window of 10 characters
  const windowSize = MINIMUM_LENGTH;
  const ratios: number[] = [];
  for (let i = 0; i <= str.length - windowSize; i++) {
    const window = str.slice(i, i + windowSize);
    const uniqueChars = new Set(window);
    ratios.push(uniqueChars.size / windowSize);
  }

  const averageRatio =
    ratios.reduce((sum, ratio) => sum + ratio, 0) / ratios.length;

  return averageRatio > 0.75;
}
